head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDINS30800.xml";
scwin.cnt = 0;
scwin.REFRESH_TIME = 60000;
scwin._timer;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 미처리현황  조회한다.
 ***********************************************/
scwin.ins_search = function() {
    // 발행일 체크
    if ($c.stf.compareFromToDate2(edt_pREQ_DD_SDATE, edt_pREQ_DD_EDATE) == false) {
        return false;
    }

    // ShowWin(grd_Grid); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS30800_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.search.select.listReqStdCdListInquiry" + "&{P}REQ_PRSN=" + txb_pREQ_PRSN.getValue() + "&{P}REQ_NO=" + txb_pREQ_NO.getValue() + "&{P}STD_CD_APPL_CONTN_TP_CD=" + $c.stf.getObjectValue(cmb_STD_CD_APPL_CONTN_TP_CD) + "&{P}REQ_DD_SDATE=" + edt_pREQ_DD_SDATE.getValue() + "&{P}REQ_DD_EDATE=" + edt_pREQ_DD_EDATE.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};



/********************************************** 
 * 함수명   : fn_goPage
 * 설명       : 그리드 클릭시 해당페이지로 이동
 ***********************************************/
scwin.fn_goPage = function(REQ_CTNT_CD, DATA_KEY_ID) {
    /*
    	01    채권                
    	02    주권                
    	03    수익증권            
    	04    신주인수권증권(WR)  
    	05    신주인수권증서(R)   
    	06    유가증권예탁증서(DR)
    	07	CP     
    	77    전자단기사채--13으로 투자계약증권이 들어오면서 77로 변경
    	08    스트립              
    	09    양도성예금증서(CD)  
    	10    주식워런트증권(ELW) 
    	11    ELS/DLS 
    	12    ETN 
    	13	투자계약증권
    	20    발행기관신규
    	21    발행기관변경
    	30    아이디신청
    	55    다운로드관리
    */
    if (dts_List.getCellData(dts_List.getRowPosition(), "DEL_CD") == "삭제신청") {
        $c.frame.path("/top").WinOpenP('INS11000');
        return;
    }
    //alert(REQ_CTNT_CD);
    if (REQ_CTNT_CD == "01") $c.frame.path("/top").WinOpenP('INS10100');
    if (REQ_CTNT_CD == "02") $c.frame.path("/top").WinOpenP('INS10000');
    if (REQ_CTNT_CD == "03") $c.frame.path("/top").WinOpenP('INS10400');
    if (REQ_CTNT_CD == "04") $c.frame.path("/top").WinOpenP('INS10600');
    if (REQ_CTNT_CD == "05") $c.frame.path("/top").WinOpenP('INS10600');
    if (REQ_CTNT_CD == "06") $c.frame.path("/top").WinOpenP('INS10500');
    if (REQ_CTNT_CD == "07") $c.frame.path("/top").WinOpenP('INS10900');
    if (REQ_CTNT_CD == "08") $c.frame.path("/top").WinOpenP('INS10700');
    if (REQ_CTNT_CD == "09") $c.frame.path("/top").WinOpenP('INS10800');
    if (REQ_CTNT_CD == "10") $c.frame.path("/top").WinOpenP('INS10300');
    if (REQ_CTNT_CD == "11") $c.frame.path("/top").WinOpenP('INS10200');
    if (REQ_CTNT_CD == "77") $c.frame.path("/top").WinOpenP('INS10900');
    if (REQ_CTNT_CD == "12") $c.frame.path("/top").WinOpenP('INS11100');
    if (REQ_CTNT_CD == "13") $c.frame.path("/top").WinOpenP('INS11200');
    if (REQ_CTNT_CD == "20") $c.frame.path("/top").WinOpenP('INS05500');
    if (REQ_CTNT_CD == "21") $c.frame.path("/top").WinOpenP('INS05600');
    if (REQ_CTNT_CD == "30") $c.frame.path("/top").WinOpenP('INS21200');
    if (REQ_CTNT_CD == "55") $c.frame.path("/top").WinOpenP('INS26500');
};
scwin.refresh_search = function(REFRESH_TIME) {
    if (scwin._timer) clearInterval(scwin._timer);
    if (scwin.REFRESH_TIME != 0) scwin._timer = setInterval(ins_search, scwin.REFRESH_TIME);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    var sToday = $c.ut.cGetToday2();
    //edt_pREQ_DD_SDATE.Text = sToday;
    //edt_pREQ_DD_EDATE.Text = sToday;	


    $c.stf.fn_setFromToDate(3, edt_pREQ_DD_SDATE, edt_pREQ_DD_EDATE);
    ins_combo_set(dts_STD_CD_APPL_CONTN_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03425", "ALL");
    dts_STD_CD_APPL_CONTN_TP_CD.insertRow();
    dts_STD_CD_APPL_CONTN_TP_CD.setCellData(dts_STD_CD_APPL_CONTN_TP_CD.getTotalRow(), "VALUE", "20");
    dts_STD_CD_APPL_CONTN_TP_CD.setCellData(dts_STD_CD_APPL_CONTN_TP_CD.getTotalRow(), "TEXT", "20 발행기관신규");
    dts_STD_CD_APPL_CONTN_TP_CD.insertRow();
    dts_STD_CD_APPL_CONTN_TP_CD.setCellData(dts_STD_CD_APPL_CONTN_TP_CD.getTotalRow(), "VALUE", "21");
    dts_STD_CD_APPL_CONTN_TP_CD.setCellData(dts_STD_CD_APPL_CONTN_TP_CD.getTotalRow(), "TEXT", "21 발행기관변경");
    dts_STD_CD_APPL_CONTN_TP_CD.insertRow();
    dts_STD_CD_APPL_CONTN_TP_CD.setCellData(dts_STD_CD_APPL_CONTN_TP_CD.getTotalRow(), "VALUE", "55");
    dts_STD_CD_APPL_CONTN_TP_CD.setCellData(dts_STD_CD_APPL_CONTN_TP_CD.getTotalRow(), "TEXT", "55 다운로드관리");
    scwin.ins_search();
    cmb_REFRESH_TIME.setSelectedIndex(2);
    scwin.refresh_search(60000);
    edt_pREQ_DD_SDATE.focus();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    scwin.cnt = rowcount;
    // CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    scwin.cnt = 0;
    // CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.txb_pREQ_NO_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pREQ_NO.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        }
    }
};
scwin.txb_pREQ_PRSN_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pREQ_PRSN.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        }
    }
};
scwin.img_pREQ_DD_SDATE_onclick = function() {
    popUpCalendar2(edt_pREQ_DD_SDATE);
};
scwin.img_pREQ_DD_EDATE_onclick = function() {
    popUpCalendar2(edt_pREQ_DD_EDATE);
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (row == 0) return;
    var isur_cd = dts_List.getCellData(row, "ISUR_CD");
    var req_ctnt_cd = dts_List.getCellData(row, "REQ_CTNT_CD");
    if (ISUR_CD.substring(0, 1) == "#" && req_ctnt_cd != "20") {
        $c.win.alert("임시 발행기관코드로 신청된 표준코드는 발행기관접수 후 가능합니다.");
        return;
    }
    scwin.fn_goPage(dts_List.getCellData(row, "REQ_CTNT_CD"), dts_List.getCellData(row, "REQ_NO"));
};
scwin.cmb_REFRESH_TIME_OnSelChange = function() {
    if (cmb_REFRESH_TIME.getSelectedIndex() == 0) {
        if (scwin._timer) clearInterval(scwin._timer);
        return;
    }
    $c.stf.setObjectValue(txb_REFRESH_TIME, "");
    scwin.REFRESH_TIME = parseInt($c.stf.getObjectValue(cmb_REFRESH_TIME)) * 1000;
    $c.win.alert("새로고침 시간이 " + $c.stf.getObjectValue(cmb_REFRESH_TIME) + "초로 설정되었습니다");
    scwin.refresh_search(scwin.REFRESH_TIME);
};
scwin.txb_REFRESH_TIME_onkeydown = function() {
    if (scwin._timer) clearInterval(scwin._timer);
};
scwin.image_1_onclick = function() {
    if ($c.stf.getObjectValue(txb_REFRESH_TIME) == "") {
        $c.win.alert("직접입력시간을 설정해 주세요");
        txb_REFRESH_TIME.focus();
        return false;
    }
    cmb_REFRESH_TIME.setSelectedIndex(0);
    scwin.REFRESH_TIME = parseInt($c.stf.getObjectValue(txb_REFRESH_TIME)) * 1000;
    $c.win.alert("새로고침 시간이 " + $c.stf.getObjectValue(txb_REFRESH_TIME) + "초로 설정되었습니다");
    scwin.refresh_search(scwin.REFRESH_TIME);
};
scwin.cmb_STD_CD_APPL_CONTN_TP_CD_OnSelChange = function() {
    scwin.ins_search();
};
